.morph-btn-box {
  width: 180px; height: 60px; border-radius: 30px;
  background: linear-gradient(90deg, #6c63ff, #00d2ff);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; position: relative; overflow: hidden;
  transition: all 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55); /* Framer Motion Spring */
  box-shadow: 0 10px 20px rgba(108, 99, 255, 0.4);
}
.morph-btn-box.clicked { width: 60px; border-radius: 50%; background: #00ffcc; box-shadow: 0 0 30px #00ffcc; }
.btn-txt { color: #fff; font-size: 18px; font-weight: bold; font-family: sans-serif; transition: opacity 0.3s; }
.morph-btn-box.clicked .btn-txt { opacity: 0; position: absolute; }
.svg-check { width: 30px; height: 30px; position: absolute; opacity: 0; transition: opacity 0.3s 0.3s; }
.morph-btn-box.clicked .svg-check { opacity: 1; }
.check-path {
  fill: none; stroke: #000; stroke-width: 4; stroke-linecap: round; stroke-linejoin: round;
  stroke-dasharray: 50; stroke-dashoffset: 50;
}
.morph-btn-box.clicked .check-path { animation: drawSVG 0.6s ease-out 0.4s forwards; }
@keyframes drawSVG { to { stroke-dashoffset: 0; } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const btn = document.createElement('div');
btn.className = 'morph-btn-box';

const txt = document.createElement('div');
txt.className = 'btn-txt';
txt.innerText = 'DOWNLOAD';

const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
svg.setAttribute("class", "svg-check");
svg.setAttribute("viewBox", "0 0 24 24");
const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
path.setAttribute("class", "check-path");
path.setAttribute("d", "M4 12 L10 18 L20 6");
svg.appendChild(path);

btn.appendChild(txt); btn.appendChild(svg); c.appendChild(btn);

btn.addEventListener('click', () => {
  btn.classList.add('clicked');
  setTimeout(() => { btn.classList.remove('clicked'); }, 3000);
});
